# Colorize text based on type and content
colorize() {
    local text="$1"
    local color_key="$2"
    
    # If colors are disabled, return plain text
    # 0 = enabled, 1 = disabled (BashFX convention)
    if [[ "$USE_COLORS" != "0" ]]; then
        echo "$text"
        return
    fi
    
    local color_code="${ANSI_COLORS[$color_key]:-}"
    local reset_code="${ANSI_COLORS[reset]}"
    
    if [[ -n "$color_code" ]]; then
        echo -e "${color_code}${text}${reset_code}"
    else
        echo "$text"
    fi
}


